			btnPrimary: { display: "inline-flex", alignItems: "center", gap: 5, height: 26, padding: "0 12px", cursor: "pointer", background: "var(--dsw-alias-brand-primary)", color: "var(--dsw-alias-label-primary-foreground)", border: "1px solid var(--dsw-alias-brand-primary)", borderRadius: 6, fontSize: 12, lineHeight: 1, whiteSpace: "nowrap", fontFamily: "inherit", boxSizing: "border-box", boxShadow: "0 1px 3px rgba(0,0,0,.35)" },
			btnDanger: { display: "inline-flex", alignItems: "center", gap: 5, height: 26, padding: "0 12px", cursor: "pointer", background: "transparent", color: "var(--dsw-alias-state-error-primary)", border: "1px solid var(--dsw-alias-state-error-primary)", borderRadius: 6, fontSize: 12, lineHeight: 1, whiteSpace: "nowrap", fontFamily: "inherit", boxSizing: "border-box", boxShadow: "0 1px 2px rgba(0,0,0,.18)" },
